//! Kitsch-specific source-native MAGNUM details. The base plain contours
//! come from eras::magnum_art and are translated in kitsch.rs; only the
//! Kitsch dark seam mask and selected-card masks live here.
//! Source: images/kitsch-store.png at 3840x2160, 2.4 native px/scene px.

use crate::style::Seg;

pub(super) const fn translated<const N: usize>(source: &[Seg; N], dx: f32, dy: f32) -> [Seg; N] {
    let mut out = *source;
    let mut i = 0;
    while i < N {
        out[i] = match out[i] {
            Seg::Move(x, y) => Seg::Move(x + dx, y + dy),
            Seg::Line(x, y) => Seg::Line(x + dx, y + dy),
            Seg::Quad { cx, cy, x, y } => Seg::Quad { cx: cx + dx, cy: cy + dy, x: x + dx, y: y + dy },
            Seg::Cubic { c1x, c1y, c2x, c2y, x, y } =>
                Seg::Cubic { c1x: c1x + dx, c1y: c1y + dy, c2x: c2x + dx, c2y: c2y + dy, x: x + dx, y: y + dy },
        };
        i += 1;
    }
    out
}

